import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0082 — Focused plugin app shell (single-plugin native apps)","description":"","frontmatter":{},"headers":[],"relativePath":"rfcs/0082-focused-plugin-app-shell.md","filePath":"rfcs/0082-focused-plugin-app-shell.md"}'),n={name:"rfcs/0082-focused-plugin-app-shell.md"};function o(r,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rfc-0082-—-focused-plugin-app-shell-single-plugin-native-apps" tabindex="-1">RFC 0082 — Focused plugin app shell (single-plugin native apps) <a class="header-anchor" href="#rfc-0082-—-focused-plugin-app-shell-single-plugin-native-apps" aria-label="Permalink to &quot;RFC 0082 — Focused plugin app shell (single-plugin native apps)&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> <code>sovereign-mobile</code> (config-driven build targets in the repo RFC 0058 establishes — <strong>not</strong> a new repository), <code>runtime/middleware.ts</code> (focused-app route lock), <code>runtime/app/(platform)/layout.tsx</code>, <code>docs/plugin-development.md</code>, <code>docs/architecture-rules.md</code>, <code>docs/self-hosting.md</code>. Depends on RFC 0080 (surface model — supplies the signal) and RFC 0081 (per-plugin installable PWA — validates the UX and supplies the icon/manifest work). Extends RFC 0058 (native mobile app shell) and mirrors RFC 0038 (desktop shell). Builds on research <a href="./../research/0006-standalone-plugin-apps.html">0006</a>.<br><strong>Incorporated into plan:</strong> Yes — epic tasks 2.27, 20.10–20.12.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Publish an individual plugin as its <strong>own</strong> native app for iOS and Android — &quot;Sovereign Tally&quot; on the App Store — while the user&#39;s Sovereign instance remains the backend, the web interface, and the source of truth. The app defaults to a primary instance URL, lets the user change it, loads only that plugin&#39;s functionality, and works offline.</p><p>It is built as an additional <strong>build target inside <code>sovereign-mobile</code></strong>, not a second codebase: the generic whole-instance Sovereign app and every focused plugin app compile from one Capacitor shell parameterized by a config file (app id, display name, icon set, default instance URL, target plugin id).</p><p>The plugin itself ships <strong>once</strong>. There is no native UI, no plugin REST API, and no second implementation — the WebView loads the same routes a browser does, and the plugin&#39;s existing Server Actions keep working unchanged.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Research 0005 established the demand: a user who lives in one app on their instance wants that app on their home screen, from the store, with an icon and a name that mean something — not a workspace they navigate into.</p><p>The critical constraint is that this must not fork the plugin ecosystem. &quot;The plugin system <em>is</em> the product&quot;, and plugins are meant to run unchanged across browser, PWA, and native. An approach where each plugin app bundles native UI and talks to a plugin-specific REST API would mean every feature ships twice — the same reason RFC 0058 rejected React Native.</p><p>The WebView approach avoids that entirely, and it adds <strong>no new architectural bet</strong>: &quot;native shell loads the remote instance in a WebView&quot; is already decided (RFC 0058) and already shipped in Tauri (<code>sovereign-desktop</code>, epic 17.1 ✅). A focused plugin app is a parameterization of a decision the project has already made and validated.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong>RFC 0058 defines the shell this extends</strong>: <code>sovereign-mobile</code> with first-launch instance URL onboarding, a persistent ordered instance list, WebView loading, navigation policy, and multi-instance switching (epic tasks 20.1–20.9, all 📋). This RFC adds build-target parameterization and the focused route lock; it does not redesign onboarding.</li><li><strong>RFC 0038&#39;s desktop equivalent has shipped</strong> (epic 17.1 ✅) — the same client model in Tauri, in the field today. Whatever this RFC establishes for focused apps should be portable to <code>sovereign-desktop</code> without redesign.</li><li><strong>RFC 0080 supplies the signal.</strong> Native shells identify themselves in the User-Agent; middleware normalizes it into <code>x-sovereign-surface</code>. This RFC extends that token with a focus component rather than inventing a parallel mechanism — the two are the same signal at the same injection point, which is why research 0005 required they be designed together.</li><li><strong>RFC 0081 supplies the per-plugin app identity</strong> — manifest, icons, scope, the login-containment rewrite. A focused native app and an installed per-plugin PWA want the same things; the native shell should not re-solve them.</li><li><strong>Auth is cookie-based for plugin surfaces.</strong> <code>sdk.auth.getSession()</code> (<code>packages/sdk/src/auth.ts:13-34</code>) reads runtime-injected headers populated by <code>runtime/middleware.ts:304</code> after verifying better-auth&#39;s signed <code>session_data</code> cookie cache. There is no per-user bearer token path.</li><li><strong>RFC 0072 is Implemented</strong> — <code>apps/auth</code> is a full OAuth 2.0/OIDC provider with <code>/oauth2/authorize</code>, <code>/token</code>, <code>/userinfo</code>, <code>/.well-known/jwks.json</code>, and admin-registered clients with exact-match redirect URIs. This is the foundation for the durable-session follow-up in §5, and its <code>allowDynamicClientRegistration: false</code> posture is the friction described there.</li><li><strong>Offline is entirely web-stack</strong> (RFC 0074/0078) and therefore inherited by any WebView unchanged — see §4.</li><li><strong><code>offline.clearAll()</code> purges on sign-out and sign-in</strong> (<code>runtime/app/(platform)/_components/AccountMenu.tsx</code>, <code>runtime/src/complete-sign-in.ts</code>), which is what makes plugin-scoped rather than user-scoped IndexedDB keys safe on a shared device.</li><li><strong>Tally declares <code>data:provide</code></strong> with four contracts, and cross-plugin consent is managed by the user in Account → Data (<code>packages/sdk/src/data.ts</code>). This is one of the concrete routes the lock must not strand — see §3.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="_1-one-shell-many-build-targets" tabindex="-1">1. One shell, many build targets <a class="header-anchor" href="#_1-one-shell-many-build-targets" aria-label="Permalink to &quot;1. One shell, many build targets&quot;">​</a></h3><p><code>sovereign-mobile</code> gains a build-config layer. Each target is a small declarative file:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;appId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fs.sovereign.tally.app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;displayName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Sovereign Tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultInstanceUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;focusPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fs.sovereign.tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;icons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./targets/tally/icons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The generic whole-instance app is simply the target with no <code>focusPlugin</code>. This keeps one navigation policy, one onboarding flow, one instance-switcher, and one WebView lifecycle for every published app — a shell fix lands once.</p><p><strong>The shell stays dumb by design</strong>: a URL, a target plugin, an icon, a scheme. It owns no auth, no roles, no plugin permissions, no session model, and no UI beyond onboarding and instance management. Everything interesting stays in the runtime, which is where the project already iterates.</p><h3 id="_2-focus-signal" tabindex="-1">2. Focus signal <a class="header-anchor" href="#_2-focus-signal" aria-label="Permalink to &quot;2. Focus signal&quot;">​</a></h3><p>The shell extends RFC 0080&#39;s User-Agent token:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sovereign-Shell/mobile-ios 1.0.0 (focus=fs.sovereign.tally)</span></span></code></pre></div><p><code>runtime/middleware.ts</code> parses it alongside the surface value and injects <code>x-sovereign-focus-plugin</code>. As with every <code>x-sovereign-*</code> header, any inbound value is stripped before the middleware injects its own.</p><h3 id="_3-route-lock-—-scope-not-security" tabindex="-1">3. Route lock — scope, not security <a class="header-anchor" href="#_3-route-lock-—-scope-not-security" aria-label="Permalink to &quot;3. Route lock — scope, not security&quot;">​</a></h3><p>When <code>x-sovereign-focus-plugin</code> is present, the runtime serves only what the focused app needs. Everything else redirects to the focused plugin&#39;s <code>routePrefix</code> rather than 404ing — the content exists and the user is entitled to it, it simply is not part of <em>this</em> app, and a 404 would misdescribe that.</p><p><strong>Allowlist</strong> (beyond the focused plugin&#39;s own prefix):</p><table tabindex="0"><thead><tr><th>Path</th><th>Why it must be reachable</th></tr></thead><tbody><tr><td><code>/login</code>, <code>/register</code>, <code>/forgot-password</code>, <code>/reset-password</code></td><td>Sign-in happens in the WebView (§5)</td></tr><tr><td><code>/account</code> and its subroutes</td><td>Password change, session revocation, <strong>and <code>data:provide</code> consent</strong> (Account → Data)</td></tr><tr><td><code>/paywall/*</code></td><td>The middleware already redirects here for monetized plugins</td></tr><tr><td><code>/offline</code></td><td>The SW document fallback</td></tr><tr><td><code>/api/*</code></td><td>Route handlers, sync endpoints, auth proxy</td></tr><tr><td>PWA/static assets</td><td>Manifest, SW, Workbox, icons, <code>_next/static</code></td></tr></tbody></table><blockquote><p><strong>Hard rule (per RFC 0080 §2):</strong> the focus signal derives from a client-controlled User-Agent and is trivially spoofable. The route lock is a <strong>product-scoping and UX mechanism, never a security boundary.</strong> Nothing behind it may rely on the lock for confidentiality — session, capability, and plugin-permission gates are unchanged and remain the only real boundaries. A user who edits their User-Agent to reach <code>/console</code> gets exactly the access their role already grants, which is the correct outcome.</p></blockquote><p>Research 0005 named this the highest-churn area of the whole design: new runtime modes accrete allowlist edge cases. The table above is the known set; the implementation should expect to extend it, and every addition should be justified in a comment rather than quietly appended.</p><p><strong>Deep links</strong> into nested plugin paths (from an email notification, say) stay within the focused plugin&#39;s prefix and are therefore allowed. Deep links to a <em>different</em> plugin redirect to the focused plugin root; the implementation should consider handing those to the system browser instead, so a notification about another app still works. Left open in §&quot;Open questions&quot;.</p><h3 id="_4-offline-—-inherited-with-one-load-bearing-constraint" tabindex="-1">4. Offline — inherited, with one load-bearing constraint <a class="header-anchor" href="#_4-offline-—-inherited-with-one-load-bearing-constraint" aria-label="Permalink to &quot;4. Offline — inherited, with one load-bearing constraint&quot;">​</a></h3><p>A focused app&#39;s offline behavior is <strong>entirely the web stack</strong> (RFC 0074/0078): the same service worker, the same <code>offline-shells</code> cache, the same <code>sdk.offline</code> IndexedDB, the same client-hydration pattern. Nothing about offline is native-specific, and that is the payoff of this approach.</p><p><strong>The constraint that makes or breaks it:</strong> service workers require an <code>https</code> document. The shell must therefore load the remote instance via Capacitor&#39;s <code>server.url</code>. Bundling web assets locally and serving them over the <code>capacitor://</code> custom scheme yields <strong>no service worker at all</strong>, and the entire offline story collapses. This is a stated, tested constraint of the shell design — not a default to be flipped later for startup-time reasons.</p><p>Research 0005 flags this as the plan&#39;s least-verified assumption. <strong>A spike against a real Capacitor build gates this RFC&#39;s implementation</strong> (epic task 20.10), because if WKWebView&#39;s service-worker behavior disappoints, the cost profile of focused native apps changes materially.</p><p><strong>Named limitation:</strong> iOS can evict <code>WKWebsiteDataStore</code> — IndexedDB and SW caches — under storage pressure or prolonged non-use. For the read cache that is a slow cold start. For an unsynced RFC 0078 write queue it is silent data loss, which is exactly that RFC&#39;s §7 concern. The eventual fix is native storage bridged through <code>sdk.device.*</code>; the honest position for the first release is a documented limitation, surfaced to the user as a pending-sync indicator rather than hidden.</p><p><strong>Sign-out purge must still fire.</strong> If sign-out moves to a native menu, the shell must drive the same web purge sites rather than clearing its own storage — otherwise a second user on a shared device inherits the first user&#39;s cached data, and with RFC 0078 their un-synced writes. The shell should navigate the WebView to the platform&#39;s own sign-out flow rather than reimplementing it.</p><h3 id="_5-auth-—-cookie-now-durable-session-named-as-the-sequel" tabindex="-1">5. Auth — cookie now, durable session named as the sequel <a class="header-anchor" href="#_5-auth-—-cookie-now-durable-session-named-as-the-sequel" aria-label="Permalink to &quot;5. Auth — cookie now, durable session named as the sequel&quot;">​</a></h3><p><strong>v1: cookie in the WebView.</strong> The instance&#39;s own login page renders in the WebView; better-auth&#39;s cookies persist in the WebView&#39;s data store; the existing middleware session gate is unchanged. Near-zero platform work, and it reuses the flow every browser user already takes.</p><p>Its weaknesses are real and accepted for v1, not hidden: iOS may purge the WebView data store, and a chrome-less focused app has no natural place to present &quot;your session expired, re-enter your password and 2FA&quot;.</p><p><strong>The sequel, designed but not built here:</strong> the shell obtains an OAuth refresh token via RFC 0072 (PKCE public client, <code>ASWebAuthenticationSession</code>, custom-scheme redirect), stores it in the OS keychain, and exchanges it for a session cookie when the WebView needs one. That yields durable sessions, silent recovery after a data purge, and biometric unlock — and it is the on-ramp to the deferred bearer-token plugin API. It is <strong>additive</strong>: nothing in this RFC&#39;s shell design has to be undone to adopt it.</p><p><strong>The friction that follow-up must resolve:</strong> RFC 0072 registers clients per-instance, admin-only, with <code>allowDynamicClientRegistration: false</code> and exact-match redirect URIs. A single published binary talking to arbitrary self-hosted instances would require every operator to hand-register a client in Console before login works — unacceptable for a store app. Either official shells get a well-known pre-registered client id provisioned at instance bootstrap, or dynamic client registration is revisited for this narrow case. Unresolved; it gates the sequel, not this RFC.</p><h3 id="_6-instance-onboarding-and-validation" tabindex="-1">6. Instance onboarding and validation <a class="header-anchor" href="#_6-instance-onboarding-and-validation" aria-label="Permalink to &quot;6. Instance onboarding and validation&quot;">​</a></h3><p>Reuse RFC 0058&#39;s onboarding (epic 20.1) and validation endpoint (epic 20.2) unchanged, with one addition: a focused app must verify that its <strong>target plugin</strong> is installed, enabled, and available on this surface before accepting an instance URL. &quot;This instance is a Sovereign instance&quot; is insufficient when the app only does one thing — a Tally app pointed at an instance without Tally should say so during onboarding, not after a confusing empty screen.</p><p>The validation response therefore needs to expose, for a requested plugin id: installed, enabled, <code>surfaces</code> compatibility (RFC 0080), and version. Epic 20.2 should design the endpoint with this consumer in mind rather than being retrofitted.</p><h3 id="_7-store-distribution-—-deliberately-rationed" tabindex="-1">7. Store distribution — deliberately rationed <a class="header-anchor" href="#_7-store-distribution-—-deliberately-rationed" aria-label="Permalink to &quot;7. Store distribution — deliberately rationed&quot;">​</a></h3><p>Research 0005&#39;s assessment stands: the code stays shared but the obligation does not. N published apps means N listings, N review cycles, N privacy declarations, N signing identities, and 1–2 weeks of review latency on every shell fix.</p><p><strong>This is handled as policy, not design:</strong> RFC 0081&#39;s installable PWA is the default answer for any plugin that wants an app-like presence; a focused native app is reserved for flagship plugins where store distribution or a native capability genuinely justifies the ongoing cost. The decision is deliberate and per-plugin, not granted on request.</p><p>Store metadata must be clear that the app connects to a user-provided instance and that Sovereign hosts nothing by default — the same requirement RFC 0058 already states. No telemetry by default.</p><h3 id="docker-config-impact" tabindex="-1">Docker / config impact <a class="header-anchor" href="#docker-config-impact" aria-label="Permalink to &quot;Docker / config impact&quot;">​</a></h3><p>None in this repository beyond RFC 0081&#39;s icon assets. The shell lives in <code>sovereign-mobile</code>.</p><h2 id="ui-flows" tabindex="-1">UI flows <a class="header-anchor" href="#ui-flows" aria-label="Permalink to &quot;UI flows&quot;">​</a></h2><p><strong>First launch, default instance:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open app → default instance URL pre-filled → validate (instance + Tally present)</span></span>
<span class="line"><span>         → load https://instance/tally in WebView → login page → signed in</span></span></code></pre></div><p><strong>Change instance:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>native menu → instance list → add/select → re-validate target plugin</span></span>
<span class="line"><span>            → WebView replaced with the new instance&#39;s /tally</span></span></code></pre></div><p><strong>Offline cold launch:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tap icon → WebView loads /tally → SW serves cached document</span></span>
<span class="line"><span>         → client hydrates from sdk.offline → cached data renders</span></span></code></pre></div><p><strong>Navigation outside the focused plugin:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>in-app link to /launcher → middleware sees x-sovereign-focus-plugin</span></span>
<span class="line"><span>                         → redirect to /tally</span></span>
<span class="line"><span>external https link      → opens in the system browser, not the shell WebView</span></span></code></pre></div><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Native UI plus a plugin REST API.</strong> Rejected — forks every plugin into a web and a native implementation, contradicting the project thesis and RFC 0058&#39;s own reasoning against React Native. Also unnecessary: the WebView calls the plugin&#39;s existing Server Actions, and the only new endpoint (offline sync) is one RFC 0078 requires regardless.</li><li><strong>A separate repository per plugin app.</strong> Rejected — every shell fix would need porting N times. One repo, N build targets.</li><li><strong>A new generic <code>sovereign-plugin-shell</code> repository</strong> distinct from <code>sovereign-mobile</code>. Rejected — the two shells are ~90% identical; splitting them guarantees divergence and doubles the store-tooling surface.</li><li><strong>Bundling web assets in the app</strong> for faster cold start. Rejected — the <code>capacitor://</code> scheme has no service worker, which would trade the entire offline story for a startup-time gain.</li><li><strong>404 for out-of-focus routes.</strong> Rejected — the content exists and the user is entitled to it; a redirect to the focused root describes the situation honestly.</li><li><strong>Enforcing the lock as a security boundary.</strong> Rejected as unsound: the signal is a spoofable User-Agent. Recorded as a hard rule so nobody later mistakes it for one.</li><li><strong>OAuth-first auth in v1.</strong> Deferred rather than rejected — it is the right end state, but it needs the client-registration friction in §5 resolved, and cookie auth ships a working app now without foreclosing it.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li>Should a cross-plugin deep link open in the system browser rather than redirecting to the focused root? Better for notifications; adds a second navigation path to reason about.</li><li>Does the focused app need a manifest opt-in (a plugin declaring it <em>may</em> be published standalone), or is that purely a build-time decision by whoever ships the app? Research 0005 left this open. Leaning build-time-only, since the lock is not a security boundary and the plugin needs no code change.</li><li>Minimum iOS/Android versions, and whether <code>sovereign-desktop</code> adopts focused targets in the same pass or later.</li><li>How the instance switcher is presented without fighting the web shell&#39;s own account UI — RFC 0058&#39;s open question 4, inherited and sharpened by chrome-less focused apps.</li><li>Whether the pending-sync indicator for the eviction limitation (§4) belongs in <code>packages/ui</code> as a shared affordance, given DS-first.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Ordered; each step gates the next. Tracked as legs 3–4 of <a href="./../workstreams/0001-standalone-plugin-apps.html">workstream 0001</a>.</p><ol><li><strong>Epic task 20.10</strong> — WKWebView service-worker + offline spike against a real Capacitor build. <strong>Gates everything below.</strong> A negative result sends this RFC back to design rather than forward to implementation.</li><li><strong>Epic task 2.27</strong> — runtime focused-app context and route lock, including the hard rule in <code>docs/architecture-rules.md</code>.</li><li><strong>Epic task 20.11</strong> — <code>sovereign-mobile</code> build-target parameterization and the first focused target.</li><li><strong>Epic task 20.12</strong> — store release process, privacy declarations, and the written rationing policy from §7.</li><li>Follow-up, unscheduled: OAuth refresh-token + session exchange (§5), pending resolution of the client-registration question.</li></ol><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>July 2026</td><td>Initial draft</td></tr></tbody></table>`,68)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
